func (q *Queries) ListUserExports(ctx context.Context, userID pgtype.UUID) ([]pgtype.UUID, error) {
	rows, err := q.db.Query(ctx, listUserExports, userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []pgtype.UUID
	for rows.Next() {
		var id pgtype.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const markExportFiles = `-- name: MarkExportFiles :exec
UPDATE export_files f SET part = $1, sidecar = v.sidecar, missing = v.missing
FROM (SELECT unnest($3::uuid[]) AS asset_id, unnest($4::boolean[]) AS sidecar,
             unnest($5::boolean[]) AS missing) v
WHERE f.export_id = $2 AND f.asset_id = v.asset_id
`

type MarkExportFilesParams struct {
	Part     pgtype.Int4
	ExportID pgtype.UUID
	AssetIds []pgtype.UUID
	Sidecars []bool
	Missing  []bool
}

func (q *Queries) MarkExportFiles(ctx context.Context, arg MarkExportFilesParams) error {
	_, err := q.db.Exec(ctx, markExportFiles,
		arg.Part,
		arg.ExportID,
		arg.AssetIds,
		arg.Sidecars,
		arg.Missing,
	)
	return err
}

